// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Scenario: Alice sends 1 ether via Put with unlockTime = 1000 at time = 500
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.warp(500);
        vm.prank(alice);
        c.Put{value: 1 ether}(1000);
        // Now attempt Collect at time = 900 (still before unlockTime = 1000)
        vm.warp(900);
        vm.prank(alice);
        bool success;
        try c.Collect(1 ether) {
            success = true;
        } catch {
            success = false;
        }
        // Reference: Collect should revert because time < unlockTime => success false
        // Mutant: Collect succeeds => success true
        // In the reference, balance remains 1 ether; in the mutant, balance becomes 0.
        // We assert that c.Acc(alice).balance is still 1 ether (the reference behavior)
        (uint unlockTime, uint balance) = c.Acc(alice);
        assertTrue(balance == 1 ether);
    }
}

