        // But vm.warp resets all? Use fresh: 
        vm.warp(1000);
        vm.prank(actor);
        c.Put{value: 2 ether}(block.timestamp + 1000);
        vm.warp(1500); // still before unlock (1500 < 2000)
        vm.prank(actor);
        bool ok2;
        try c.Collect(1 ether) { ok2 = true; } catch { ok2 = false; }
        (uint u2, uint b2) = c.Acc(actor);
        // In reference: ok2 false (revert), balance stays 2 ether.
        // In buggy: ok2 true, balance becomes 1 ether.
        assertTrue(!ok2 && b2 == 2 ether || ok2 && b2 == 1 ether); // This is not a final assertion. We need a single fact.
        // Actually we need one assertion that reference holds and bug breaks. Use: in correct, ok2 == false. So assertTrue(!ok2) passes on correct, fails on buggy.
        assertTrue(!ok2);
    }
}

